import base64
import io
import json
import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _to_bytes(document: Any) -> bytes:
    if document is None:
        raise ValueError("document is required")

    if isinstance(document, bytes):
        return document

    if isinstance(document, bytearray):
        return bytes(document)

    if isinstance(document, str):
        if document.startswith("data:") and "," in document:
            _, b64_data = document.split(",", 1)
            return base64.b64decode(b64_data)
        if os.path.exists(document):
            with open(document, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(document, validate=True)
        except Exception as e:
            raise ValueError("document string must be a file path or base64-encoded content") from e

    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data

    raise TypeError("Unsupported document type")


def _money_to_schema(amount_obj: Any) -> Optional[Dict[str, Any]]:
    if not amount_obj:
        return None
    if isinstance(amount_obj, dict):
        amount = amount_obj.get("Value") or amount_obj.get("Amount")
        currency = amount_obj.get("Currency") or amount_obj.get("CurrencyCode")
    else:
        amount = getattr(amount_obj, "value", None) or getattr(amount_obj, "Value", None)
        currency = getattr(amount_obj, "currency", None) or getattr(amount_obj, "Currency", None)
    if amount is None and currency is None:
        return None
    return {"amount": amount, "currency": currency}


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    if isinstance(field, dict):
        for key in ("Value", "value", "Text", "text", "Content", "content"):
            if key in field and field[key] is not None:
                return field[key]
        return field
    for attr in ("value", "Value", "text", "Text", "content", "Content"):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return val
    return field


def _normalize_line_items(expense_doc: Any) -> list:
    line_items = []
    summaries = getattr(expense_doc, "SummaryFields", None) or getattr(expense_doc, "summary_fields", None) or []
    items = getattr(expense_doc, "LineItemGroups", None) or getattr(expense_doc, "line_item_groups", None) or []

    # Textract AnalyzeExpense exposes LineItemGroups with LineItems and ExpenseDocuments with SummaryFields.
    for group in items:
        line_group_items = getattr(group, "LineItems", None) or getattr(group, "line_items", None) or []
        for item in line_group_items:
            fields = getattr(item, "ExpenseFields", None) or getattr(item, "expense_fields", None) or []
            normalized = {}
            for f in fields:
                key = _field_value(getattr(f, "Type", None) or getattr(f, "type", None))
                val = getattr(f, "ValueDetection", None) or getattr(f, "value_detection", None)
                normalized[str(key).lower() if key is not None else "unknown"] = _field_value(val)
            if normalized:
                line_items.append(normalized)

    # Fallback: derive from summary fields if no structured line items returned.
    if not line_items and summaries:
        normalized = {}
        for f in summaries:
            key = _field_value(getattr(f, "Type", None) or getattr(f, "type", None))
            val = getattr(f, "ValueDetection", None) or getattr(f, "value_detection", None)
            normalized[str(key).lower() if key is not None else "unknown"] = _field_value(val)
        if normalized:
            line_items.append(normalized)

    return line_items


def extract_expense_fields(document: Any, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.

    Input:
        document: file path, bytes, base64 string, or file-like object

    Output schema:
        {
          "vendor_name": str|None,
          "invoice_id": str|None,
          "invoice_date": str|None,
          "due_date": str|None,
          "subtotal": {"amount": ..., "currency": ...} | None,
          "tax": {"amount": ..., "currency": ...} | None,
          "tip": {"amount": ..., "currency": ...} | None,
          "total": {"amount": ..., "currency": ...} | None,
          "payment_method": str|None,
          "currency": str|None,
          "line_items": [...],
          "raw_provider_response": {...}
        }
    """
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    textract = boto3.client("textract", region_name=region)

    payload = _to_bytes(document)

    try:
        response = textract.analyze_expense(Document={"Bytes": payload})
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract AnalyzeExpense failed: {e}") from e

    expense_documents = response.get("ExpenseDocuments", []) or []

    normalized = {
        "vendor_name": None,
        "invoice_id": None,
        "invoice_date": None,
        "due_date": None,
        "subtotal": None,
        "tax": None,
        "tip": None,
        "total": None,
        "payment_method": None,
        "currency": None,
        "line_items": [],
        "raw_provider_response": response,
    }

    if not expense_documents:
        return normalized

    doc = expense_documents[0]
    summary_fields = doc.get("SummaryFields", []) or []

    for field in summary_fields:
        ftype = _field_value(field.get("Type")) if isinstance(field, dict) else _field_value(getattr(field, "Type", None))
        value_detection = field.get("ValueDetection") if isinstance(field, dict) else getattr(field, "ValueDetection", None)
        text = _field_value(value_detection)

        if ftype is None:
            continue

        key = str(ftype).upper()

        if key == "VENDOR_NAME":
            normalized["vendor_name"] = text
        elif key in ("INVOICE_RECEIPT_ID", "INVOICE_ID", "RECEIPT_ID"):
            normalized["invoice_id"] = text
        elif key in ("INVOICE_RECEIPT_DATE", "INVOICE_DATE", "RECEIPT_DATE"):
            normalized["invoice_date"] = text
        elif key in ("DUE_DATE",):
            normalized["due_date"] = text
        elif key in ("SUBTOTAL",):
            normalized["subtotal"] = _money_to_schema(value_detection)
        elif key in ("TAX", "TAX_AMOUNT"):
            normalized["tax"] = _money_to_schema(value_detection)
        elif key in ("TIP", "GRATUITY"):
            normalized["tip"] = _money_to_schema(value_detection)
        elif key in ("TOTAL", "AMOUNT_DUE", "AMOUNT_PAID"):
            if normalized["total"] is None:
                normalized["total"] = _money_to_schema(value_detection)
        elif key in ("CURRENCY",):
            normalized["currency"] = text
        elif key in ("PAYMENT_METHOD", "PAYMENT_TYPE"):
            normalized["payment_method"] = text

    # Determine currency from any monetary field if not explicitly present
    for money_field in (normalized["subtotal"], normalized["tax"], normalized["tip"], normalized["total"]):
        if money_field and money_field.get("currency"):
            normalized["currency"] = normalized["currency"] or money_field["currency"]
            break

    normalized["line_items"] = _normalize_line_items(doc)

    return normalized


def main(document: Any, region_name: Optional[str] = None) -> str:
    return json.dumps(extract_expense_fields(document, region_name=region_name), ensure_ascii=False)
